-- 成果治理：成果与研究/资助/伦理/数据关联、作者身份核验和状态治理。
BEGIN;

CREATE TABLE IF NOT EXISTS "科研成果关联" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "成果类型" integer NOT NULL,
    "成果编号" integer NOT NULL,
    "关联类型" varchar(10) NOT NULL,
    "流程模板编号" integer,
    "项目编号" integer,
    "外部对象类型" varchar(30),
    "外部对象编号" varchar(100),
    "关联说明" varchar(1000),
    "建立人编号" integer NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研成果关联" PRIMARY KEY ("编号"),
    CONSTRAINT "ck_科研成果关联_类型" CHECK ("关联类型" IN ('研究','资助','伦理','数据','其他')),
    CONSTRAINT "ck_科研成果关联_对象" CHECK (
        ("流程模板编号" IS NOT NULL AND "项目编号" IS NOT NULL)
        OR ("外部对象类型" IS NOT NULL AND "外部对象编号" IS NOT NULL)
    )
);

CREATE UNIQUE INDEX IF NOT EXISTS "uq_科研成果关联_项目"
    ON "科研成果关联" ("成果类型", "成果编号", "关联类型", "流程模板编号", "项目编号")
    WHERE "流程模板编号" IS NOT NULL AND "项目编号" IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS "uq_科研成果关联_外部对象"
    ON "科研成果关联" ("成果类型", "成果编号", "关联类型", "外部对象类型", "外部对象编号")
    WHERE "外部对象类型" IS NOT NULL AND "外部对象编号" IS NOT NULL;

CREATE TABLE IF NOT EXISTS "科研成果作者核验" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "成果类型" integer NOT NULL,
    "成果编号" integer NOT NULL,
    "作者编号" integer NOT NULL,
    "作者顺序" integer,
    "作者显示姓名" varchar(100),
    "单位名称" varchar(200),
    "ORCID" varchar(50),
    "身份状态" varchar(10) NOT NULL DEFAULT '待核验',
    "核验说明" varchar(1000),
    "核验人编号" integer,
    "核验时间" timestamp without time zone,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研成果作者核验" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_科研成果作者核验_作者" UNIQUE ("成果类型", "成果编号", "作者编号"),
    CONSTRAINT "ck_科研成果作者核验_状态" CHECK ("身份状态" IN ('待核验','已核验','需更正','无法匹配')),
    CONSTRAINT "ck_科研成果作者核验_顺序" CHECK ("作者顺序" IS NULL OR "作者顺序" > 0)
);

CREATE INDEX IF NOT EXISTS "ix_科研成果作者核验_状态"
    ON "科研成果作者核验" ("身份状态", "成果类型", "成果编号");

CREATE TABLE IF NOT EXISTS "科研成果治理" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "成果类型" integer NOT NULL,
    "成果编号" integer NOT NULL,
    "状态" varchar(10) NOT NULL DEFAULT '有效',
    "规范成果类型" integer,
    "规范成果编号" integer,
    "治理原因" varchar(1000),
    "操作人编号" integer NOT NULL,
    "操作时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研成果治理" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_科研成果治理_成果" UNIQUE ("成果类型", "成果编号"),
    CONSTRAINT "ck_科研成果治理_状态" CHECK ("状态" IN ('有效','待更正','已更正','已撤稿','重复')),
    CONSTRAINT "ck_科研成果治理_重复目标" CHECK ("状态" <> '重复' OR ("规范成果类型" IS NOT NULL AND "规范成果编号" IS NOT NULL))
);

CREATE INDEX IF NOT EXISTS "ix_科研成果治理_状态"
    ON "科研成果治理" ("状态", "操作时间" DESC);

UPDATE "系统迁移版本"
   SET "版本" = 47,
       "脚本" = '001-047',
       "检查摘要" = '增加成果与研究资助伦理数据关联、作者核验和成果状态治理'
 WHERE "编号" = 1;

COMMIT;
